import{_ as t,l,o as e,c as o,v as r,p as E,x as i,d,i as m,S as s}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"杠杆、保证金与强平","description":"","frontmatter":{"title":"杠杆、保证金与强平","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/leverage-liquidation.md","filePath":"quant/leverage-liquidation.md","lastUpdated":1789023840000}'),h={name:"quant/leverage-liquidation.md"};function p(u,a,B,c,A,f){const n=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="杠杆、保证金与强平" tabindex="-1">杠杆、保证金与强平 <a class="header-anchor" href="#杠杆、保证金与强平" aria-label="Permalink to &quot;杠杆、保证金与强平&quot;">​</a></h1><div class="epigraph"><p>市场流动性与融资流动性互相喂养：价格下跌削弱抵押品，保证金上调迫使变现，变现再打压价格。杠杆把这一环写成账户规则，强平是规则的角点，不是外生的意外。</p><footer>—— Brunnermeier and Pedersen, Market Liquidity and Funding Liquidity, Review of Financial Studies, 2009</footer></div><p><a href="/quant/var-backtest">上一课</a>用 Kupiec 的无条件覆盖与 Christoffersen 的独立性检验声明的 \\(p\\)：99% 日 VaR 年样本期望违反极少，不拒绝不是验证，次数检验也不能当作 ES 回测。缺口是纸面损失假设价格外生、持有期能走完：有杠杆时维持水平被击穿则非自愿变现，真实路径含被迫在不利价格上交易的段。Brunnermeier–Pedersen 的螺旋与 Adrian–Shin 的主动杠杆，使去杠杆成为价格的供给冲击。本课写账户算术与强平反馈，不重写覆盖检验。对象是风险架构，不是如何把他人逼到清算阈值。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>覆盖检验回答的是声明的 \\(p\\) 有没有被次数与独立性打脸。留下的是：那条损失路径是否假设你能持有到期末。无杠杆时，损失以权益为限，变现时间可以由投资人选择。有杠杆时，名义头寸 \\(N\\) 远大于权益 \\(E\\)，杠杆 \\(\\lambda=N/E\\)。价格反向移动 \\(\\Delta P\\) 使权益变成 \\(E&#39;=E+N\\cdot\\Delta P\\)（符号按方向），杠杆升到 \\(N/E&#39;\\)。若 \\(E&#39;\\) 低于维持保证金要求 \\(m_{\\mathrm{maint}}\\cdot N\\)，经纪人要求追加现金；若在时限内不到账，就按规则减名义，直到保证金恢复或头寸清零。问题是把这套规则写成对 \\(L\\) 的改写：真实损失路径含有<strong>被迫在不利价格上交易</strong>的段，这段不出现在未加保证金约束的 VaR 里。</p><p>第二句话是内生性。个体的强平是账户问题；许多账户共享同类抵押品、同类风险因子时，强平是市场价格的供给冲击。Brunnermeier–Pedersen 区分市场流动性（变现对价格的冲击）与融资流动性（用抵押品借钱的难易）：两者在压力里螺旋。风险系统若把价格过程当外生、再在外生路径上算保证金，会低估同时去杠杆的尾部。Jorion 讨论流动性风险时强调：VaR 地平线上未必能按标记价退出；强平规则把「未必」变成「必须立刻退出」。</p><h3 id="初始、维持与变异保证金" tabindex="-1">初始、维持与变异保证金 <a class="header-anchor" href="#初始、维持与变异保证金" aria-label="Permalink to &quot;初始、维持与变异保证金&quot;">​</a></h3><p>期货风格的变异保证金每日把盈亏兑成现金，维持的是保证金账户余额；股票融资则把证券当抵押，贷款余额相对市值有折扣（haircut）。折扣升等价于初始保证金升：同样权益能支持的 \\(N\\) 下降。维持水平低于初始，是为了给价格噪声一个缓冲，避免一碰到就平仓；缓冲越窄，强平越频繁。交易所与经纪商的保证金模型（SPAN、基于 VaR 的保证金等）把 \\(m\\) 写成风险的函数，于是 \\(m\\) 在波动上升时上调——融资流动性在最需要时收紧。这是制度，不是微观结构故障。</p><p><span class="marginnote">强平价格通常差于当时中间价：它走市价、吃深度、可能穿过涨跌停后的缺口。用中间价算「触及维持保证金时的账面损失」会低估真实权益消耗，也会低估对其它账户的冲击。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>单账户、单一资产、多头融资买入：价格从 \\(P\\) 到 \\(P(1+r)\\)，权益 \\(E&#39;=E+N r\\)。维持约束 \\(E&#39;\\ge m N\\)。临界收益</p> \\[r_{\\mathrm{liq}}= \\frac{m N-E}{N}= m-\\frac{1}{\\lambda}. \\]<p>杠杆越高、维持保证金越高，反向一点点就触及。触及后若不允许补仓或补仓失败，名义必须降到 \\(N&#39;\\le E&#39;/m_{\\mathrm{init}}\\)（回到初始水平）或清零。出售量为 \\(N-N&#39;\\)，在薄市场上的冲击把 \\(r\\) 进一步打低，可能触发下一轮。这就是损失螺旋（价格跌→权益跌）与保证金螺旋（\\(m\\) 升→必须卖更多）的算术。</p><p>组合层用保证金模型输出一个总要求 \\(M_t\\)，约束 \\(E_t\\ge M_t\\)。\\(M_t\\) 若按组合 VaR 或 SPAN 情景随 \\(\\sigma_t\\) 与相关性上升，则与风险模型同源：同一个高 \\(\\sigma\\) 既提高 VaR 限额压力，又提高保证金。回测纸面 VaR 而不回测「是否触发 \\(E\\lt M\\)」，会漏掉账户的真正死亡方式。Kelly 公式给出的增长最优仓位在有强平时不再可行：触及清算的路径把对数效用打到 \\(-\\infty\\) 的离散版本，分数 Kelly 与硬杠杆上限是对这一角点的工程响应，见 <a href="/quant/kelly-sizing">仓位与 Kelly</a>。</p><h3 id="螺旋何时成为市场现象" tabindex="-1">螺旋何时成为市场现象 <a class="header-anchor" href="#螺旋何时成为市场现象" aria-label="Permalink to &quot;螺旋何时成为市场现象&quot;">​</a></h3><p>个体强平成为价格冲击，需要：头寸相对当时深度足够大，或许多账户同时同向。后者在拥挤策略、指数再平衡、同类 VaR 模型同步削减时出现。Adrian–Shin 的机制是主动杠杆目标：银行不想要、也往往不被允许，在资产下跌后维持高 \\(\\lambda\\)，于是卖资产。Brunnermeier–Pedersen 的机制是保证金对波动与冲击内生上升。两者叠加时，供给曲线在下跌市场里向右下弯：越跌越卖。Thurner 等人的模拟显示，无杠杆时近正态的收益，加上杠杆与强平阈值后出现肥尾与波动聚类——看起来像 <a href="/quant/garch">GARCH</a> 或 <a href="/quant/evt">EVT</a> 要拟合的对象，生成机制却是融资约束而不是外生跳。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>保证金是看跌期权的抵押版本：贷方拒绝在 \\(E\\) 过低时继续承担违约。强平是执行该保护。对市场而言，保护的执行把潜在违约转换成立即的市价供给。价格因而在融资压力期不再只反映信息与存货，还反映谁必须卖。这与做市商 <a href="/quant/toxic-flow">停报价</a> 互相反馈：深度下降使同等出售的冲击更大，更多账户触及 \\(r_{\\mathrm{liq}}\\)。O&#39;Hara 的微观结构价格形成，在这里被加上一层融资状态变量。</p><p>从风险度量看，真实损失分布在杠杆下是截断加冲击：未强平时像纸面 P&amp;L，强平后变成「在不可选的时间、以冲击后的价格实现」。ES 对这些路径特别敏感，因为它们正是尾巴。Artzner 公理的正齐次在此处紧张：名义翻倍不只使线性损失翻倍，还使触及强平的概率非线性上升。要把杠杆写进风险，或者把 \\(L\\) 定义为已施加保证金规则的账户损益，或者在纸面 ES 上加一项融资流动性附加。只提高 \\(\\alpha\\) 而不改 \\(L\\) 的定义，是在用更极端的外生分位数去近似一个内生机制，通常近似得很差。</p><p><span class="marginnote">隔夜跳空可以越过维持水平而不断触发盘中追加，直接开盘强平。日频 VaR 把跳空放进 \\(L\\)，但仍假定你能在次日以标记价调整名义。跳空后的第一笔成交往往已经是清算流。</span></p><h3 id="与实施缺口、做市库存的对照" tabindex="-1">与实施缺口、做市库存的对照 <a class="header-anchor" href="#与实施缺口、做市库存的对照" aria-label="Permalink to &quot;与实施缺口、做市库存的对照&quot;">​</a></h3><p>投资组合的 <a href="/quant/implementation-shortfall">实施缺口</a> 是自愿执行相对决策价的成本；强平是非自愿执行，决策价是保证金规则而不是投资观点。做市的库存限额是内部 \\(q_{\\max}\\)，触及后偏度与停报价是内部控制；经纪商保证金是外部硬约束，通常更粗、更同步、更不顾你的公允中点。架构上应把内部限额设在外部强平之前，使「自己减仓」发生在「被减仓」之前。内部限额若与外部保证金用同一套 VaR，压力期会同时触发，缓冲为零。这是参数选择，不是理论必然。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>上述算术忽略交叉保证金、期权非线性、多币种、以及司法上的破产留存。真实经纪规则含有酌情权：可以提前提高 haircut、拒绝加仓、延长或缩短追加时限。模型把规则当确定性阈值，会低估酌情收紧、高估在阈值前的安全。跨市场的抵押品再抵押链（Adrian–Shin 所强调的）使同一证券支撑多层杠杆，haircut 的一小步可以沿链放大。</p><p>风险报告若只给纸面 VaR 与 ES，应至少附加：当前杠杆、距维持水平的缓冲（价格距离与资金距离）、集中抵押品、以及压力 haircut 情景下的强制卖出规模。回测应包含「是否触及追加、是否被减仓」，而不是只有 Kupiec 的违反次数。监管与内部模型把流动性期限写进 FRTB 一类框架，正是承认 \\(h\\) 日标记不是 \\(h\\) 日可变现。Geanakoplos 的教训是杠杆本身是均衡价格的一部分；把杠杆当外生常数，价格理论不完整，风险管理也不完整。</p><p><span class="marginnote">本篇说明强平如何成为损失机制与系统性反馈，不提供如何定位他人保证金阈值、如何交易清算流的任何路径。那些问题属于对脆弱账户的利用，不是风险管理架构。</span></p>',26)),(e(),E(s,null,{default:i(()=>[m(n,{id:"mermaid-74",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E6%9D%83%E7%9B%8A%20E%2C%20%E5%90%8D%E4%B9%89%20N%22%5D%20--%3E%20Lam%5B%22%E6%9D%A0%E6%9D%86%20%CE%BB%20%3D%20N%2FE%22%5D%0A%20%20Lam%20--%3E%20Buf%5B%22%E8%B7%9D%E7%BB%B4%E6%8C%81%E4%BF%9D%E8%AF%81%E9%87%91%E7%9A%84%E7%BC%93%E5%86%B2%22%5D%0A%20%20Px%5B%22%E4%BB%B7%E6%A0%BC%E4%B8%8D%E5%88%A9%E5%8F%98%E5%8A%A8%22%5D%20--%3E%20E%0A%20%20M%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E7%8E%87%20m%20%E9%9A%8F%E6%B3%A2%E5%8A%A8%E4%B8%8A%E8%B0%83%22%5D%20--%3E%20Buf%0A%20%20Buf%20--%3E%7C%22%E7%BC%93%E5%86%B2%E8%80%97%E5%B0%BD%22%7C%20Liq%5B%22%E5%BC%BA%E5%B9%B3%3A%20%E9%9D%9E%E8%87%AA%E6%84%BF%E5%8F%98%E7%8E%B0%22%5D%0A%20%20Liq%20--%3E%20Imp%5B%22%E5%B8%82%E5%9C%BA%E5%86%B2%E5%87%BB%22%5D%0A%20%20Imp%20--%3E%20Px%0A%20%20Imp%20--%3E%20Tox%5B%22%E6%B7%B1%E5%BA%A6%E4%B8%8B%E9%99%8D%20%2F%20%E5%81%9C%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20Tox%20--%3E%20Imp%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>杠杆把保证金规则写进损失路径：维持水平被击穿则非自愿变现，纸面 VaR 的外生价格假设失效。</li><li>临界反向收益约为 \\(m-1/\\lambda\\)；杠杆与保证金率共同决定缓冲。</li><li>Brunnermeier–Pedersen 的损失螺旋与保证金螺旋，以及 Adrian–Shin 的主动杠杆，使去杠杆成为价格的供给冲击。</li><li>强平路径落在 ES 的尾巴里，且使正齐次的连贯度量与真实流动性成本分家。</li><li>内部库存或风险限额应严于外部强平，并避免与保证金模型在同一信号上同时触发。</li><li>回测除违反次数外，应记录追加与减仓事件；跳空可以越过盘中缓冲。</li><li>出处：Brunnermeier and Pedersen, <em>RFS</em>, 2009；Adrian and Shin, <em>Journal of Financial Intermediation</em>, 2010；Shleifer and Vishny, <em>Journal of Finance</em>, 1997；Geanakoplos, <em>NBER Macroeconomics Annual</em>, 2010；Thurner, Farmer and Geanakoplos, <em>Quantitative Finance</em>, 2012；VaR 与流动性语境见 Jorion, <em>Value at Risk</em>。</li></ul>',2))])}const P=t(h,[["render",p]]);export{q as __pageData,P as default};
